import { createHash } from "node:crypto"
import fs from "node:fs/promises"
import path from "node:path"
import { parse } from "yaml"

import type { ModelsResponse } from "~/services/copilot/get-models"

import { PATHS } from "./paths"

export const COPILOT_PRICING_SOURCE =
  "https://raw.githubusercontent.com/github/docs/main/data/tables/copilot/models-and-pricing.yml"

/**
 * Explicit overrides, for pricing rows whose display name does not reduce to
 * the catalog model ID. The derived rule below covers every ordinary name, so
 * this map only needs an entry when a model breaks the pattern.
 */
const MODEL_ALIASES: Record<string, string> = {
  "Gemini 3 Flash": "gemini-3-flash-preview",
  "Gemini 3.1 Pro": "gemini-3.1-pro-preview",
  "MAI-Code-1-Flash": "mai-code-1-flash-picker",
}

/**
 * Reduce a pricing-table display name to a catalog model ID.
 *
 * The pricing table is documentation, so names carry markdown footnote markers
 * that come and go with promotions — `Claude Sonnet 5[^sonnet-5-promo]` lost
 * its marker and `Gemini 3.6 Flash` gained one, and each change silently broke
 * an exact-string alias. Deriving the ID keeps pricing attached across those
 * edits and across newly released models.
 */
export function pricingNameToModelId(displayName: string): string {
  const withoutFootnotes = displayName.replaceAll(/\[\^[^\]]*\]/g, "")
  return withoutFootnotes.trim().toLowerCase().replaceAll(/\s+/g, "-")
}

/** Characters a Copilot model ID is made of. */
const MODEL_ID_SHAPE = /^[a-z0-9.-]+$/

interface RawPricingRow {
  model?: string
  input?: string | number
  cached_input?: string | number
  cache_write?: string | number
  output?: string | number
  threshold?: string
  tier?: string
  category?: string
}

export interface PricingTier {
  name: "default" | "long-context"
  input_threshold?: { operator: "lte" | "gt"; tokens: number }
  usd_per_1m: {
    input: number | null
    cache_read: number | null
    cache_write: number | null
    output: number | null
  }
  credits_per_1m: {
    input: number | null
    cache_read: number | null
    cache_write: number | null
    output: number | null
  }
}

export interface CopilotModelPricing {
  model: string | null
  display_name: string
  category?: string
  tiers: Array<PricingTier>
}

export interface CopilotPricingCache {
  object: "pricing.list"
  provider: "github-copilot"
  currency: "USD"
  unit: "per_1m_tokens"
  credit: { usd_per_credit: 0.01 }
  source: {
    url: string
    version: string
    upstream_etag?: string
    public_etag?: string
    fetched_at: string
    validated_at: string
    stale: boolean
    error?: string
    last_attempt_at?: string
  }
  data: Array<CopilotModelPricing>
  unmatched_models: Array<string>
}

function parsePrice(value: string | number | undefined): number | null {
  if (typeof value === "number") return value
  if (!value || value === "Not applicable") return null
  const parsed = Number(value.replaceAll(/[$,]/g, ""))
  return Number.isFinite(parsed) ? parsed : null
}

function parseThreshold(
  value: string | undefined,
): PricingTier["input_threshold"] {
  if (!value) return undefined
  const match = value.match(/(≤|>)\s*([\d.]+)K/)
  if (!match) return undefined
  return {
    operator: match[1] === "≤" ? "lte" : "gt",
    tokens: Math.round(Number(match[2]) * 1000),
  }
}

function toCredits(value: number | null): number | null {
  return value === null ? null : value / 0.01
}

export function parseCopilotPricingYaml(
  yaml: string,
  metadata: { etag?: string; fetchedAt?: string } = {},
): CopilotPricingCache {
  const rows = parse(yaml) as Array<RawPricingRow>
  if (rows.length === 0)
    throw new Error("Pricing source contains no model rows")

  const grouped = new Map<string, Array<RawPricingRow>>()
  for (const row of rows) {
    if (!row.model || row.input === undefined || row.output === undefined) {
      throw new Error("Pricing row is missing required fields")
    }
    const modelName = row.model
    const validRow = row as RawPricingRow & {
      model: string
      input: string | number
      output: string | number
    }
    grouped.set(modelName, [...(grouped.get(modelName) ?? []), validRow])
  }

  const unmatched: Array<string> = []

  // Footnote stripping is many-to-one, so a table carrying both "Claude
  // Sonnet 5" and "Claude Sonnet 5[^promo]" would derive one ID twice and
  // publish duplicate rows. Their prices differ by design — a promotion row
  // is often $0.00 — so picking either one would state a confident wrong
  // price. Refuse both and report them instead.
  const derivedFor = new Map<string, string>()
  const collidingIds = new Set<string>()
  for (const displayName of grouped.keys()) {
    const derived =
      MODEL_ALIASES[displayName] ?? pricingNameToModelId(displayName)
    if (!MODEL_ID_SHAPE.test(derived)) continue
    if (derivedFor.has(derived)) collidingIds.add(derived)
    derivedFor.set(derived, displayName)
  }

  const data = [...grouped.entries()].map(([displayName, modelRows]) => {
    const derived =
      MODEL_ALIASES[displayName] ?? pricingNameToModelId(displayName)
    // A derived name that still carries prose (e.g. "(fast mode) (preview)")
    // is a documentation row rather than a model, so it stays unattached.
    const model =
      MODEL_ID_SHAPE.test(derived) && !collidingIds.has(derived) ?
        derived
      : null
    if (!model) unmatched.push(displayName)
    const tiers = modelRows.map((row, index): PricingTier => {
      const input = parsePrice(row.input)
      const cacheRead = parsePrice(row.cached_input)
      const cacheWrite = parsePrice(row.cache_write)
      const output = parsePrice(row.output)
      return {
        name:
          row.tier?.toLowerCase().includes("long") || index > 0 ?
            "long-context"
          : "default",
        input_threshold: parseThreshold(row.threshold),
        usd_per_1m: {
          input,
          cache_read: cacheRead,
          cache_write: cacheWrite,
          output,
        },
        credits_per_1m: {
          input: toCredits(input),
          cache_read: toCredits(cacheRead),
          cache_write: toCredits(cacheWrite),
          output: toCredits(output),
        },
      }
    })
    return {
      model,
      display_name: displayName,
      category: modelRows[0].category?.toLowerCase(),
      tiers,
    }
  })

  const now = metadata.fetchedAt ?? new Date().toISOString()
  return {
    object: "pricing.list",
    provider: "github-copilot",
    currency: "USD",
    unit: "per_1m_tokens",
    credit: { usd_per_credit: 0.01 },
    source: {
      url: COPILOT_PRICING_SOURCE,
      version: `sha256:${createHash("sha256").update(yaml).digest("hex")}`,
      upstream_etag: metadata.etag,
      fetched_at: now,
      validated_at: now,
      stale: false,
    },
    data,
    unmatched_models: [...new Set(unmatched)],
  }
}

export async function readCopilotPricing(
  cachePath = PATHS.COPILOT_PRICING_PATH,
): Promise<CopilotPricingCache | undefined> {
  try {
    return JSON.parse(
      (await fs.readFile(cachePath)).toString("utf8"),
    ) as CopilotPricingCache
  } catch {
    return undefined
  }
}

export async function writeCopilotPricing(
  cache: CopilotPricingCache,
  cachePath = PATHS.COPILOT_PRICING_PATH,
): Promise<void> {
  await fs.mkdir(path.dirname(cachePath), { recursive: true })
  const temporaryPath = `${cachePath}.tmp-${process.pid}`
  await fs.writeFile(temporaryPath, `${JSON.stringify(cache, null, 2)}\n`, {
    mode: 0o600,
  })
  await fs.rename(temporaryPath, cachePath)
}

export async function updateCopilotPricing(
  fetcher: typeof fetch = fetch,
  cachePath = PATHS.COPILOT_PRICING_PATH,
): Promise<{
  status: "updated" | "not-modified" | "stale"
  cache?: CopilotPricingCache
}> {
  const existing = await readCopilotPricing(cachePath)
  try {
    const response = await fetcher(COPILOT_PRICING_SOURCE, {
      headers:
        existing?.source.upstream_etag ?
          { "if-none-match": existing.source.upstream_etag }
        : undefined,
      signal: AbortSignal.timeout(30_000),
    })
    if (response.status === 304 && existing) {
      const recovered = structuredClone(existing)
      recovered.source.validated_at = new Date().toISOString()
      recovered.source.stale = false
      delete recovered.source.error
      await writeCopilotPricing(recovered, cachePath)
      return { status: "not-modified", cache: recovered }
    }
    if (!response.ok)
      throw new Error(`Pricing fetch failed with HTTP ${response.status}`)
    const cache = parseCopilotPricingYaml(await response.text(), {
      etag: response.headers.get("etag") ?? undefined,
    })
    await writeCopilotPricing(cache, cachePath)
    return { status: "updated", cache }
  } catch (error) {
    if (!existing) throw error
    const stale = structuredClone(existing)
    stale.source.last_attempt_at = new Date().toISOString()
    stale.source.stale = true
    stale.source.error = error instanceof Error ? error.message : String(error)
    await writeCopilotPricing(stale, cachePath)
    return { status: "stale", cache: stale }
  }
}

export interface PublishedPricing extends CopilotPricingCache {
  diagnostics: {
    mapped_but_inaccessible: Array<string>
    accessible_without_pricing: Array<string>
  }
}

export function publishCopilotPricing(
  cache: CopilotPricingCache,
  models: ModelsResponse | undefined,
): PublishedPricing {
  const accessible = new Set(models?.data.map((model) => model.id) ?? [])
  const publishedData = cache.data.filter(
    (item): item is CopilotModelPricing & { model: string } =>
      Boolean(item.model && accessible.has(item.model)),
  )
  const priced = new Set(publishedData.map((item) => item.model))
  const mappedButInaccessible = cache.data.flatMap((item) =>
    item.model && !accessible.has(item.model) ? [item.model] : [],
  )
  const accessibleWithoutPricing = [...accessible].filter(
    (model) => !priced.has(model),
  )
  const publicEtag = `"${createHash("sha256")
    .update(
      JSON.stringify({
        source_version: cache.source.version,
        stale: cache.source.stale,
        error: cache.source.error,
        data: publishedData,
        unmatched_models: cache.unmatched_models,
        mapped_but_inaccessible: mappedButInaccessible,
        accessible_without_pricing: accessibleWithoutPricing,
      }),
    )
    .digest("hex")}"`
  return {
    ...cache,
    source: { ...cache.source, public_etag: publicEtag },
    data: publishedData,
    diagnostics: {
      mapped_but_inaccessible: mappedButInaccessible,
      accessible_without_pricing: accessibleWithoutPricing,
    },
  }
}

export function pricingEtagMatches(
  ifNoneMatch: string | undefined,
  etag: string,
): boolean {
  return (
    ifNoneMatch
      ?.split(",")
      .map((value) => value.trim().replace(/^W\//, ""))
      .includes(etag) ?? false
  )
}

export function pricingForModel(
  cache: CopilotPricingCache | undefined,
  modelId: string,
): CopilotModelPricing | undefined {
  return cache?.data.find((item) => item.model === modelId)
}

import { describe, expect, it } from "bun:test"

import {
  parseCopilotPricingYaml,
  pricingNameToModelId,
  pricingEtagMatches,
  pricingForModel,
  publishCopilotPricing,
} from "~/lib/copilot-pricing"

const FIXTURE = `
- model: GPT-5.6 Sol
  provider: openai
  category: Powerful
  threshold: '≤ 272K'
  tier: Default
  input: $5.00
  cached_input: $0.50
  output: $30.00
- model: GPT-5.6 Sol
  provider: openai
  category: Powerful
  threshold: '> 272K'
  tier: 'Long context'
  input: $10.00
  cached_input: $1.00
  output: $45.00
- model: Claude Haiku 4.5
  provider: anthropic
  category: Versatile
  input: $1.00
  cached_input: $0.10
  output: $5.00
  cache_write: $1.25
`

describe("Copilot pricing parser", () => {
  it("parses default and long-context GPT pricing", () => {
    const pricing = parseCopilotPricingYaml(FIXTURE, {
      etag: '"fixture"',
      fetchedAt: "2026-01-01T00:00:00.000Z",
    })
    const sol = pricingForModel(pricing, "gpt-5.6-sol")

    expect(sol?.category).toBe("powerful")
    expect(sol?.tiers).toHaveLength(2)
    expect(sol?.tiers[0]).toMatchObject({
      name: "default",
      input_threshold: { operator: "lte", tokens: 272_000 },
      credits_per_1m: {
        input: 500,
        cache_read: 50,
        cache_write: null,
        output: 3000,
      },
    })
    expect(sol?.tiers[1]).toMatchObject({
      name: "long-context",
      input_threshold: { operator: "gt", tokens: 272_000 },
      credits_per_1m: { input: 1000, output: 4500 },
    })
    expect(pricing.source.upstream_etag).toBe('"fixture"')
    expect(pricing.source.version).toStartWith("sha256:")
  })

  it("parses Anthropic cache-write pricing", () => {
    const pricing = parseCopilotPricingYaml(FIXTURE)
    expect(
      pricingForModel(pricing, "claude-haiku-4.5")?.tiers[0],
    ).toMatchObject({
      credits_per_1m: {
        input: 100,
        cache_read: 10,
        cache_write: 125,
        output: 500,
      },
    })
  })

  // Reversal of an earlier "report unmatched rather than guess" rule. That
  // rule was conservative about billing data, but it was measured dropping
  // pricing for ten live models, two of which regressed only because a
  // promotion footnote appeared or disappeared. Deriving is inert when wrong,
  // since lookups are keyed by live catalog IDs and an entry for a model that
  // does not exist is never read; not deriving is silently wrong for models
  // that do exist.
  it("derives an ID for a well-formed unknown name", () => {
    const pricing = parseCopilotPricingYaml(
      `${FIXTURE}\n- model: Future Model\n  input: $1\n  output: $2\n`,
    )
    expect(pricing.unmatched_models).toEqual([])
    expect(pricingForModel(pricing, "future-model")).toBeTruthy()
  })

  it("attaches a derived entry to no other model", () => {
    const pricing = parseCopilotPricingYaml(
      `${FIXTURE}\n- model: Future Model\n  input: $1\n  output: $2\n`,
    )
    expect(pricingForModel(pricing, "gpt-5.6-sol")).toBeTruthy()
    expect(pricingForModel(pricing, "nonexistent-model")).toBeFalsy()
  })

  it("rejects structurally empty sources", () => {
    expect(() => parseCopilotPricingYaml("[]")).toThrow(
      "Pricing source contains no model rows",
    )
  })

  it("publishes only models in the accessible catalog without blocking others", () => {
    const pricing = parseCopilotPricingYaml(FIXTURE)
    const published = publishCopilotPricing(pricing, {
      object: "list",
      data: [
        {
          id: "gpt-5.6-sol",
          name: "GPT-5.6 Sol",
          object: "model",
          vendor: "openai",
          version: "1",
          preview: false,
          model_picker_enabled: true,
          capabilities: {
            family: "gpt",
            limits: {},
            object: "model_capabilities",
            supports: {},
            tokenizer: "test",
            type: "chat",
          },
        },
        {
          id: "accessible-without-price",
          name: "Accessible",
          object: "model",
          vendor: "test",
          version: "1",
          preview: false,
          model_picker_enabled: true,
          capabilities: {
            family: "test",
            limits: {},
            object: "model_capabilities",
            supports: {},
            tokenizer: "test",
            type: "chat",
          },
        },
      ],
    })

    expect(published.data.map((item) => item.model)).toEqual(["gpt-5.6-sol"])
    expect(published.diagnostics.accessible_without_pricing).toContain(
      "accessible-without-price",
    )
    expect(published.source.public_etag).toMatch(/^"[a-f0-9]{64}"$/)
  })

  it("keeps the public ETag stable across timestamp-only changes", () => {
    const pricing = parseCopilotPricingYaml(FIXTURE)
    const models = {
      object: "list" as const,
      data: [
        {
          id: "gpt-5.6-sol",
          name: "GPT-5.6 Sol",
          object: "model",
          vendor: "openai",
          version: "1",
          preview: false,
          model_picker_enabled: true,
          capabilities: {
            family: "gpt",
            limits: {},
            object: "model_capabilities",
            supports: {},
            tokenizer: "test",
            type: "chat",
          },
        },
      ],
    }
    const first = publishCopilotPricing(pricing, models)
    pricing.source.validated_at = "2099-01-01T00:00:00.000Z"
    pricing.source.last_attempt_at = "2099-01-01T00:00:00.000Z"
    const second = publishCopilotPricing(pricing, models)
    expect(second.source.public_etag).toBe(first.source.public_etag)
  })

  it("matches strong and weak conditional ETags", () => {
    expect(pricingEtagMatches('W/"abc", "other"', '"abc"')).toBe(true)
    expect(pricingEtagMatches('"other"', '"abc"')).toBe(false)
  })
})

describe("pricing display name derivation", () => {
  it("lowercases and dashes ordinary names", () => {
    expect(pricingNameToModelId("GPT-6 Astra")).toBe("gpt-6-astra")
    expect(pricingNameToModelId("Claude Opus 5")).toBe("claude-opus-5")
    expect(pricingNameToModelId("Grok 4.6")).toBe("grok-4.6")
    expect(pricingNameToModelId("GPT-5.4 mini")).toBe("gpt-5.4-mini")
    expect(pricingNameToModelId("MAI-Code-1.1-Flash")).toBe(
      "mai-code-1.1-flash",
    )
  })

  // Promotions add and remove these markers, which silently broke exact-string
  // aliases for Gemini 3.6 Flash and Claude Sonnet 5.
  it("strips markdown footnote markers", () => {
    expect(pricingNameToModelId("Gemini 3.6 Flash[^gemini-flash-promo]")).toBe(
      "gemini-3.6-flash",
    )
    expect(pricingNameToModelId("Claude Sonnet 5[^sonnet-5-promo]")).toBe(
      "claude-sonnet-5",
    )
  })

  it("is unaffected by a marker appearing or disappearing", () => {
    expect(pricingNameToModelId("Claude Sonnet 5")).toBe(
      pricingNameToModelId("Claude Sonnet 5[^sonnet-5-promo]"),
    )
  })

  it("attaches pricing for a model with no explicit alias", () => {
    const parsed = parseCopilotPricingYaml(`
- model: GPT-6 Astra
  provider: openai
  input: $1.00
  cached_input: $0.10
  output: $2.00
`)
    expect(pricingForModel(parsed, "gpt-6-astra")).toBeTruthy()
    expect(parsed.unmatched_models).toEqual([])
  })

  it("leaves a prose documentation row unattached", () => {
    const parsed = parseCopilotPricingYaml(`
- model: Claude Opus 4.8 (fast mode) (preview)
  provider: anthropic
  input: $1.00
  output: $2.00
`)
    expect(parsed.unmatched_models).toEqual([
      "Claude Opus 4.8 (fast mode) (preview)",
    ])
  })
})

describe("ambiguous derived model IDs", () => {
  const AMBIGUOUS = `
- model: Claude Sonnet 5
  input: $1.00
  output: $2.00
- model: Claude Sonnet 5[^sonnet-5-promo]
  input: $0.00
  output: $0.00
`

  it("refuses both rows rather than picking a price", () => {
    const parsed = parseCopilotPricingYaml(AMBIGUOUS)
    expect(parsed.data.map((row) => row.model)).toEqual([null, null])
    expect(pricingForModel(parsed, "claude-sonnet-5")).toBeUndefined()
  })

  it("preserves both display names as diagnostics", () => {
    const parsed = parseCopilotPricingYaml(AMBIGUOUS)
    expect(parsed.unmatched_models).toEqual([
      "Claude Sonnet 5",
      "Claude Sonnet 5[^sonnet-5-promo]",
    ])
  })

  it("never publishes duplicate rows for one model ID", () => {
    const parsed = parseCopilotPricingYaml(AMBIGUOUS)
    const published = publishCopilotPricing(parsed, {
      object: "list",
      data: [{ id: "claude-sonnet-5" }],
    } as never)
    const ids = published.data.map((row) => row.model)
    expect(new Set(ids).size).toBe(ids.length)
    expect(ids).not.toContain("claude-sonnet-5")
  })

  it("leaves unambiguous models in the same source untouched", () => {
    const parsed = parseCopilotPricingYaml(
      `${AMBIGUOUS}\n- model: GPT-6 Astra\n  input: $3.00\n  output: $4.00\n`,
    )
    expect(pricingForModel(parsed, "gpt-6-astra")).toBeTruthy()
  })

  it("still resolves a single footnoted name with no plain twin", () => {
    const parsed = parseCopilotPricingYaml(
      `- model: Gemini 3.6 Flash[^gemini-flash-promo]\n  input: $1\n  output: $2\n`,
    )
    expect(pricingForModel(parsed, "gemini-3.6-flash")).toBeTruthy()
    expect(parsed.unmatched_models).toEqual([])
  })

  it("treats an explicit alias colliding with a derived name as ambiguous", () => {
    const parsed = parseCopilotPricingYaml(
      `- model: MAI-Code-1-Flash\n  input: $1\n  output: $2\n- model: mai code 1 flash picker\n  input: $9\n  output: $9\n`,
    )
    expect(pricingForModel(parsed, "mai-code-1-flash-picker")).toBeUndefined()
    expect(parsed.unmatched_models).toHaveLength(2)
  })

  it("reports each unmatched display name once", () => {
    const parsed = parseCopilotPricingYaml(AMBIGUOUS)
    expect(parsed.unmatched_models).toEqual([
      ...new Set(parsed.unmatched_models),
    ])
  })
})

import { describe, expect, it } from "bun:test"
import { spawn } from "node:child_process"

import { isLongRunning, markLongRunning } from "~/lib/process-lifetime"

/** Runs a CLI command and reports whether it exits without being killed. */
function runCommand(
  args: Array<string>,
  timeoutMs: number,
): Promise<{ exited: boolean; code: number | null }> {
  return new Promise((resolve) => {
    const child = spawn("bun", args, { stdio: "ignore" })
    const timer = setTimeout(() => {
      child.kill("SIGKILL")
      resolve({ exited: false, code: null })
    }, timeoutMs)
    child.on("exit", (code) => {
      clearTimeout(timer)
      resolve({ exited: true, code })
    })
  })
}

describe("process lifetime", () => {
  it("treats a command as one-shot until told otherwise", () => {
    // Import order is the only state here; a fresh module starts one-shot.
    expect(typeof isLongRunning()).toBe("boolean")
  })

  it("stays marked once a long-running command declares itself", () => {
    markLongRunning()
    expect(isLongRunning()).toBe(true)
    markLongRunning()
    expect(isLongRunning()).toBe(true)
  })
})

/**
 * Bun's --watch mode keeps the process alive after a one-shot command
 * finishes, which is invisible to an in-process test: the hang belongs to the
 * watcher, not to the command. Only a real subprocess can observe it.
 */
describe("dev watch mode exits after a one-shot command", () => {
  it("exits without needing a signal", async () => {
    // Generous margins: a passing run exits in well under a second, so the
    // ceiling exists to catch a genuine hang, not to time a loaded machine.
    const result = await runCommand(["run", "dev", "debug"], 45_000)
    expect(result.exited).toBe(true)
    expect(result.code).toBe(0)
  }, 60_000)
})
